import { useState } from 'react';
import { JxButton, JxInput } from '@jinx-ui/react';

interface RegistrationData {
  name: string;
  email: string;
  phone: string;
  street: string;
  city: string;
  zip: string;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY_DATA: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  street: '',
  city: '',
  zip: '',
};

interface RegistrationFormProps {
  onSubmit: (data: RegistrationData) => void;
}

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [stepIndex, setStepIndex] = useState(0);
  const [data, setData] = useState<RegistrationData>(EMPTY_DATA);

  const isLastStep = stepIndex === STEPS.length - 1;

  const updateField = (field: keyof RegistrationData) => (value: string) => {
    setData((prev) => ({ ...prev, [field]: value }));
  };

  const handleNext = () => {
    if (isLastStep) {
      onSubmit(data);
      return;
    }
    setStepIndex((i) => Math.min(i + 1, STEPS.length - 1));
  };

  const handleBack = () => {
    setStepIndex((i) => Math.max(i - 1, 0));
  };

  return (
    <div
      className="jx-card"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-lg)',
        padding: 'var(--jx-space-lg)',
        maxWidth: 420,
      }}
    >
      <ol
        aria-label="Шаги регистрации"
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          listStyle: 'none',
          margin: 0,
          padding: 0,
        }}
      >
        {STEPS.map((label, index) => {
          const isActive = index === stepIndex;
          const isDone = index < stepIndex;
          return (
            <li
              key={label}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 'var(--jx-space-xs)',
                flex: 1,
              }}
            >
              <span
                aria-current={isActive ? 'step' : undefined}
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: 24,
                  height: 24,
                  borderRadius: 'var(--jx-radius-full)',
                  fontSize: 'var(--jx-font-size-sm)',
                  color: isActive || isDone ? 'var(--jx-color-on-primary)' : 'var(--jx-color-fg-muted)',
                  background: isActive || isDone ? 'var(--jx-color-primary)' : 'var(--jx-color-bg-muted)',
                  border: '1px solid var(--jx-color-border)',
                }}
              >
                {index + 1}
              </span>
              <span
                style={{
                  fontSize: 'var(--jx-font-size-sm)',
                  color: isActive ? 'var(--jx-color-fg)' : 'var(--jx-color-fg-muted)',
                  fontWeight: isActive ? 'var(--jx-font-weight-medium)' : 'var(--jx-font-weight-regular)',
                }}
              >
                {label}
              </span>
            </li>
          );
        })}
      </ol>

      {stepIndex === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-md)' }}>
          <JxInput label="Имя" value={data.name} onValueChange={updateField('name')} />
          <JxInput label="Email" type="email" value={data.email} onValueChange={updateField('email')} />
          <JxInput label="Телефон" type="tel" value={data.phone} onValueChange={updateField('phone')} />
        </div>
      )}

      {stepIndex === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-md)' }}>
          <JxInput label="Улица и дом" value={data.street} onValueChange={updateField('street')} />
          <JxInput label="Город" value={data.city} onValueChange={updateField('city')} />
          <JxInput label="Индекс" value={data.zip} onValueChange={updateField('zip')} />
        </div>
      )}

      {stepIndex === 2 && (
        <dl
          style={{
            display: 'grid',
            gridTemplateColumns: 'auto 1fr',
            gap: 'var(--jx-space-xs) var(--jx-space-md)',
            margin: 0,
          }}
        >
          <dt style={{ color: 'var(--jx-color-fg-muted)' }}>Имя</dt>
          <dd style={{ margin: 0 }}>{data.name || '—'}</dd>
          <dt style={{ color: 'var(--jx-color-fg-muted)' }}>Email</dt>
          <dd style={{ margin: 0 }}>{data.email || '—'}</dd>
          <dt style={{ color: 'var(--jx-color-fg-muted)' }}>Телефон</dt>
          <dd style={{ margin: 0 }}>{data.phone || '—'}</dd>
          <dt style={{ color: 'var(--jx-color-fg-muted)' }}>Адрес</dt>
          <dd style={{ margin: 0 }}>
            {[data.street, data.city, data.zip].filter(Boolean).join(', ') || '—'}
          </dd>
        </dl>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-sm)' }}>
        <JxButton variant="secondary" onClick={handleBack} disabled={stepIndex === 0}>
          Назад
        </JxButton>
        <JxButton variant="primary" onClick={handleNext}>
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </div>
  );
}

